import{_ as t,c as a,o as n,ae as r}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Delete Exchange Rate","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-exchange-rate","title":"Delete Exchange Rate","description":"Delete a single exchange rate by its IRI. The deleted record is returned in the response.","query":"mutation DeleteAdminSettingsExchangeRate($input: deleteAdminSettingsExchangeRateInput!) {\\n  deleteAdminSettingsExchangeRate(input: $input) {\\n    adminSettingsExchangeRate {\\n      _id\\n      targetCurrency\\n      targetCurrencyCode\\n      targetCurrencyName\\n      rate\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/exchange-rates/35\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsExchangeRate\\": {\\n      \\"adminSettingsExchangeRate\\": {\\n        \\"_id\\": 35,\\n        \\"targetCurrency\\": 92,\\n        \\"targetCurrencyCode\\": \\"QDD\\",\\n        \\"targetCurrencyName\\": \\"Audit Demo Currency\\",\\n        \\"rate\\": 2.25,\\n        \\"message\\": \\"Exchange rate deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/exchange-rates/delete.md","filePath":"api/graphql-api/admin/settings/exchange-rates/delete.md"}'),d={name:"api/graphql-api/admin/settings/exchange-rates/delete.md"};function o(i,e,s,c,l,h){return n(),a("div",null,e[0]||(e[0]=[r('<h1 id="delete-exchange-rate" tabindex="-1">Delete Exchange Rate <a class="header-anchor" href="#delete-exchange-rate" aria-label="Permalink to &quot;Delete Exchange Rate&quot;">​</a></h1><p>Removes a single exchange rate. The currency itself is not affected — only the conversion entry is deleted.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsExchangeRate(input:)</code></td><td>Mutation</td><td>Delete one exchange rate</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>yes</td><td>IRI of the exchange rate to delete.</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The returned node is an in-memory snapshot of the just-deleted record — its scalar fields (<code>_id</code>, <code>targetCurrency</code>, <code>targetCurrencyCode</code>, <code>targetCurrencyName</code>, <code>rate</code>) still resolve so you can confirm exactly which row was removed.</li><li>Select <strong><code>message</code></strong> for the success confirmation — it resolves to <code>&quot;Exchange rate deleted successfully.&quot;</code> on a successful delete. <code>message</code> is <code>null</code> on read / list / create / update; a failed delete returns a top-level <code>errors[]</code> entry instead.</li><li>Do <strong>not</strong> select the node&#39;s IRI <code>id</code> field on this mutation — the IRI cannot be generated for a deleted record and the field resolves with an <code>errors[]</code> entry. Select <code>_id</code> instead, as shown.</li><li>An unknown id returns <code>Exchange rate not found.</code> (equivalent to HTTP 404).</li></ul><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative <code>id</code>. Replace it with a rate that exists in your store — use the <a href="./list.html"><code>adminSettingsExchangeRates</code></a> query to discover valid ids.</p></div><p>Permission: <code>settings.exchange_rates.delete</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p></div>',11)]))}const p=t(d,[["render",o]]);export{g as __pageData,p as default};
